98:       try {
99:         const res = await fetch(`${import.meta.env.VITE_API_URL || 'https://odizopetcare.onrender.com'}/api/imagekit/upload`, {
100:           method: 'POST',
101:           headers: { 'Content-Type': 'application/json' },
102:           body: JSON.stringify({
103:             file: reader.result,
104:             fileName: `pet_${Date.now()}_${file.name}`,
